        print(json.dumps({'path':path,'meta':res.meta}),flush=True)
    except Exception as e:
        print('ERROR',repr(e),flush=True)
        if 'Connection' in repr(e):
            r.wait_ready(); print(json.dumps(r.status()),flush=True)
